41	/// Parses a query feature that starts with a feature name.
42	///
43	/// This covers boolean features such as `color`, plain features such as
44	/// `(width: 500px)`, and name-first range features such as `(width <= 500px)`.
45	#[inline]
46	fn parse_named_query_feature(p: &mut CssParser) -> ParsedSyntax {
47	    if !is_at_query_feature_name(p) {
48	        return Absent;
49	    }
50	
51	    let m = p.start();
52	    parse_query_feature_name(p).or_add_diagnostic(p, expected_identifier);
53	
54	    let kind = if is_at_query_feature_range_comparison(p) {
55	        // Checked by `is_at_query_feature_range_comparison` above.
56	        parse_query_feature_range_comparison(p).ok();
57	        parse_any_query_feature_value(p).or_add_diagnostic(p, expected_query_feature_value);
58	        CSS_QUERY_FEATURE_RANGE
59	    } else if p.at(T![:]) {
60	        p.bump(T![:]);
61	        parse_any_query_feature_value(p).or_add_diagnostic(p, expected_query_feature_value);
62	        CSS_QUERY_FEATURE_PLAIN
63	    } else {
64	        CSS_QUERY_FEATURE_BOOLEAN
65	    };
66	
67	    Present(m.complete(p, kind))
68	}
