83	#[inline]
84	fn parse_interpolated_query_feature(p: &mut CssParser) -> ParsedSyntax {
85	    if !is_at_scss_interpolation(p) {
86	        return Absent;
87	    }
88	
89	    let feature_start = p.checkpoint();
90	
91	    // Interpolation can start either a feature name or a feature value.
92	    // Classify from what follows the interpolation so we only speculate over
93	    // the ambiguous prefix instead of the whole feature.
94	    // Guarded by `is_at_scss_interpolation` above.
95	    parse_scss_regular_interpolation(p).ok();
96	
97	    if p.at(T![:]) || !is_at_query_feature_range_comparison(p) {
98	        p.rewind(feature_start);
99	        return parse_named_query_feature(p);
100	    }
101	
102	    // Checked by `is_at_query_feature_range_comparison` above.
103	    parse_query_feature_range_comparison(p).ok();
104	
105	    if !is_at_query_feature_name(p) {
106	        p.rewind(feature_start);
107	        return parse_named_query_feature(p);
108	    }
109	
110	    // Checked by `is_at_query_feature_name` above.
111	    parse_query_feature_name(p).ok();
112	    p.rewind(feature_start);
